import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
import yaml
import hashlib
import hmac

app = Flask(__name__)

SECRET = os.environ.get('WEBHOOK_SECRET', 'default-secret')
ALLOWED_TEMPLATES = ['deploy', 'rollback', 'scale', 'restart']

def verify_signature(payload, signature):
    expected = hmac.new(SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

def sanitize_template_name(name):
    # Block directory traversal attempts
    if '..' in name or '/' in name or '\\' in name:
        return None
    if name not in ALLOWED_TEMPLATES:
        return None
    return name

def render_manifest(template_name, variables):
    """Load a YAML template and substitute variables"""
    template_path = f'/app/templates/{template_name}.yaml'
    if not os.path.exists(template_path):
        return None, 'Template not found'

    with open(template_path, 'r') as f:
        template_content = f.read()

    # Substitute variables into template
    for key, value in variables.items():
        template_content = template_content.replace(f'${{{key}}}', str(value))

    return template_content, None

def apply_manifest(manifest_content, namespace):
    """Apply the rendered manifest to the cluster"""
    with tempfile.NamedTemporaryFile(mode='w', suffix='.yaml', delete=False) as f:
        f.write(manifest_content)
        tmp_path = f.name

    try:
        # Apply to specific namespace
        cmd = f'kubectl apply -f {tmp_path} -n {namespace}'
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=30
        )
        return result.returncode == 0, result.stdout + result.stderr
    finally:
        os.unlink(tmp_path)

@app.route('/api/v1/deploy', methods=['POST'])
def deploy():
    sig = request.headers.get('X-Signature', '')
    if not verify_signature(request.data, sig):
        return jsonify({'error': 'Invalid signature'}), 401

    try:
        payload = yaml.safe_load(request.data)
    except yaml.YAMLError:
        return jsonify({'error': 'Invalid YAML payload'}), 400

    template = sanitize_template_name(payload.get('template', ''))
    if not template:
        return jsonify({'error': 'Invalid template'}), 400

    namespace = payload.get('namespace', 'default')
    variables = payload.get('variables', {})

    # Render the manifest with user-provided variables
    manifest, err = render_manifest(template, variables)
    if err:
        return jsonify({'error': err}), 400

    # Apply the manifest
    success, output = apply_manifest(manifest, namespace)
    if success:
        return jsonify({'status': 'applied', 'output': output})
    else:
        return jsonify({'error': 'Apply failed', 'output': output}), 500

@app.route('/api/v1/status', methods=['GET'])
def status():
    ns = request.args.get('namespace', 'default')
    resource = request.args.get('resource', 'pods')
    # Command injection via namespace parameter
    cmd = f'kubectl get {resource} -n {ns} -o json'
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=15)
    if result.returncode == 0:
        return jsonify(yaml.safe_load(result.stdout))
    return jsonify({'error': result.stderr}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
